-- model_effect_catalog.lua
--
-- WHAT THIS ANSWERS
--   MODEL.MRG holds, for every monster model, four variant images ("MODEL
--   effects"): one per guardian-star selection in each battle slot.
--   Model_LoadMonsterMergeStage stages 7..10 copy the one that matches
--   ModelSlot.guardian_star_selection to 0x8013B000 (slot 0, the attacker) or
--   0x8017B000 (slot 1, the defender). Each image starts with its North
--   American header word and has its handler at +4. notes/model-effects.csv
--   maps 332 headers to original eNNN names; the other 318 only have the
--   hNNN fallback, and the helpers inside most images still have structural
--   names. Nothing at runtime computes effect ids, so a trace cannot recover
--   file names. It can say, for each 3D battle the human plays, which image
--   loaded in each slot, for which model/card and guardian star, and which of
--   that image's functions actually ran, first hit and hit count. With the
--   human's description of the effect that supports descriptive helper names
--   and confirms the model -> image tables in notes/overlays/model-variants.md.
--
--   Every Vsync the script reads the header word at each slot base and the
--   slot's variant data pointer (ModelSlot + 0xDEC). A new pair opens an
--   episode: header, eNNN/hNNN name, model id (ModelSlot + 0xDF8), the card
--   assumed to be model id + 1 (Cosmo Queen: model 707, card 708) and
--   guardian_star_selection (ModelSlot + 0xDFE), and whether the embedded
--   tables expect that model/selection to load this header. It then arms an
--   execution breakpoint on every function entry the per-image metadata
--   lists, each only once its first instruction matches the retail word. The
--   episode ends when the header or the data pointer changes (the image is
--   cleared at the end of a battle); its breakpoints are disabled, never
--   removed, and re-enabled if a later image has a function at the same
--   address.
--
--   The embedded catalog covers all 650 North American variant images that
--   load at the two slot bases (config/slus_01411/overlays/model_variant_*
--   and model_image_* metadata, 1,370 function entries; first instruction
--   words from the verified module images) plus the 722 card names and
--   guardian stars from notes/card-catalog.csv. It was generated by a
--   throwaway script; the trace is scaffolding and is deleted once its result
--   is folded into the notes.
--
-- HOW TO RUN (about five minutes once the script is loaded)
--   North American disc. Any Free Duel or campaign duel works, as long as
--   3D battles play (the game skips them when the CPU attacks, so the
--   player attacks the CPU). Use as many different monsters as possible.
--   1. Open PCSX-Redux with the game and enable the debugger. Select the
--      interpreter CPU (restart the emulator if you switch).
--   2. Start the duel and set up your first attack. Do not load the script
--      before this point: it stops itself five minutes after loading.
--   3. Debug -> Lua editor, paste this file. Check that the setup line and
--      the "armed" line appear.
--   4. Attack. Watch the 3D battle and note the t= of each START row and of
--      anything distinctive the effect draws. Repeat with other monsters.
--      Try at least one monster with its second guardian star.
--   5. It prints its document after eight episodes (four battles), five
--      minutes after it was loaded, or on reset. Copy the whole document into
--      tools/trace/result/model_effect_catalog.txt and fill in the context.
--
-- WHAT TO WRITE IN THE CONTEXT
--   One line per #NN: which monster attacked which, the guardian star each
--   had, and what the effect looked like (shapes, colours, motion), with the
--   t= of distinctive moments so they can be matched to the "first" rows.
--
-- LUA STACK OVERFLOW
--   PCSX-Redux builds before grumpycoders/pcsx-redux d303204c (2026-10-18)
--   leave two tables on an event listener's coroutine stack per event, so a
--   GPU::Vsync listener overflows after about nine minutes. This script
--   stops itself after five. A later "stack overflow" message from an old
--   build is harmless once the document has been copied.

local ffi = require('ffi')

local SCRIPT_NAME = 'model_effect_catalog'
-- Breakpoints fire only while the debugger setting is on and the interpreter
-- CPU is the engine actually running. PCSX-Redux reads the debugger flag live,
-- so a script can switch it on itself. The CPU engine is chosen at emulator
-- start and Lua cannot query it: the Dynarec setting only says what the next
-- start will use. The setup therefore counts as confirmed only once one of
-- this script's execution breakpoints has fired. Runs before any breakpoint
-- is installed.
local TRACE_SETUP = (function()
    local okSettings, emulator = pcall(function()
        return PCSX.settings.emulator
    end)
    if not okSettings or emulator == nil then
        return 'unknown: PCSX.settings unavailable; enable the debugger and '
            .. 'select the interpreter CPU by hand'
    end
    local debugger = 'unknown'
    local okDebug, debugOn = pcall(function() return emulator.Debug.Debug end)
    if okDebug and debugOn == true then
        debugger = 'on'
    elseif okDebug and debugOn == false then
        pcall(function() emulator.Debug.Debug = true end)
        local _, now = pcall(function() return emulator.Debug.Debug end)
        debugger = now == true and 'enabled-by-script'
            or 'OFF: enable Configuration -> Emulation -> Debugger'
    end
    local configured = 'unknown'
    local okDynarec, dynarecOn = pcall(function() return emulator.Dynarec end)
    if okDynarec and dynarecOn == false then
        configured = 'interpreter'
    elseif okDynarec and dynarecOn == true then
        configured = 'DYNAREC: breakpoints will not fire; select the '
            .. 'interpreter CPU and restart the emulator'
    end
    return 'debugger=' .. debugger .. ' configured_cpu=' .. configured
        .. ' active_cpu=unverified'
end)()
print(SCRIPT_NAME .. ': setup ' .. TRACE_SETUP)

-- Every breakpoint goes through here so the first real hit can confirm the
-- running engine. The wrapped invoker's return value is passed through.
local traceExecutionObserved = false
local function traceAddBreakpoint(address, kind, width, cause, invoker)
    if invoker == nil then
        return PCSX.addBreakpoint(address, kind, width, cause)
    end
    return PCSX.addBreakpoint(address, kind, width, cause, function(...)
        if not traceExecutionObserved then
            traceExecutionObserved = true
            pcall(print, SCRIPT_NAME .. ': execution breakpoint observed; '
                .. 'setup confirmed')
        end
        return invoker(...)
    end)
end
local function traceExecutionStatus()
    if traceExecutionObserved then
        return 'execution_breakpoint=observed'
    end
    return 'execution_breakpoint=NOT-observed: the setup is unverified and '
        .. 'silence is not evidence'
end

local RAM_BASE = 0x80000000
local RAM_END = 0x80200000
local FPS = 60
local SLOTS = 0x800f2c40
local SLOT_SIZE = 0xe20
local VARIANT_DATA = 0xdec
local MODEL_ID = 0xdf8
local GUARDIAN_STAR = 0xdfe
local BASES = {[0] = 0x8013b000, [1] = 0x8017b000}

local MAX_EPISODES = 8
local MAX_ROWS = 400
local MAX_HIT_ROWS = 160
local MAX_UNKNOWN_ROWS = 8
local MAX_BREAKPOINTS = 200
-- A function whose first word has not arrived this long after the header
-- did is reported as a signature mismatch and left unarmed.
local SIGNATURE_WAIT_FRAMES = 120
-- Old PCSX-Redux builds leak two Lua stack slots per Vsync event and
-- overflow at about 32,750 events; five minutes stays well inside that.
local TIMEOUT_FRAMES = 300 * FPS

