'Chakra/Mercury/Moon','Crab Turtle/Neptune/Jupiter','Mikazukinoyaiba/Sun/Uranus','Meteor Dragon/Uranus/Neptune',
'Meteor B. Dragon/Mars/Sun','Firewing Pegasus/Mars/Moon','Psycho-Puppet/Moon/Saturn','Garma Sword/Moon/Uranus',
'Javelin Beetle/Jupiter/Uranus','Fortress Whale/Neptune/Saturn','Dokurorider/Uranus/Mars','Mask of Shine & Dark/Venus/Pluto',
'Dark Magic Ritual//','Magician of Black Chaos/Mercury/Mars',
}
-- END GENERATED CATALOG

local mem = PCSX.getMemPtr()

local function inRam(addr, size)
    return addr ~= nil and addr >= RAM_BASE and addr + size <= RAM_END
end
local function u8(addr)
    if mem == nil or not inRam(addr, 1) then return nil end
    return tonumber(ffi.cast('uint8_t*', mem + (addr - RAM_BASE))[0])
end
local function u16(addr)
    if mem == nil or not inRam(addr, 2) or addr % 2 ~= 0 then return nil end
    return tonumber(ffi.cast('uint16_t*', mem + (addr - RAM_BASE))[0])
end
local function u32(addr)
    if mem == nil or not inRam(addr, 4) or addr % 4 ~= 0 then return nil end
    return tonumber(ffi.cast('uint32_t*', mem + (addr - RAM_BASE))[0])
end
local function show(v, fmt)
    if v == nil then return 'unreadable' end
    return string.format(fmt or '%d', v)
end

local frames = 0
local rows, dropped = {}, 0
local hitRows, unknownRows = 0, 0
local episodes, closed = 0, 0
local current = {}
local lastSeen = {}
local summaries = {}
-- address -> function record of the open episode that armed it
local targets = {}
local breakpointCount = 0
local stray, foreign, mismatched, unarmed = 0, 0, 0, 0
local callbackError = nil
local done = false

-- Printing never raises into the emulator's callback path.
local function say(text)
    pcall(print, text)
end

local function stamp(frame)
    return string.format('t=%6.1fs', (frame or frames) / FPS)
end

local function live(text)
    say(text)
    if #rows < MAX_ROWS then rows[#rows + 1] = text else dropped = dropped + 1 end
end

local function work(slot)
    local w = u32(SLOTS + slot * SLOT_SIZE + VARIANT_DATA)
    if w == nil or w == 0 or w % 4 ~= 0 or not inRam(w, 4) then return nil end
    return w
end

local function card(model, selection)
    local entry = model and CARDS[model + 1]
    if entry == nil then return 'card=unknown' end
    local name, star1, star2 = entry:match('^(.*)/([^/]*)/([^/]*)$')
    local star = selection == 0 and star1 or selection == 1 and star2 or '?'
    return string.format('card=%d "%s" star=%s', model + 1, name,
                         star ~= '' and star or 'none')
end

local function expected(entry, model, selection)
    if model == nil or selection == nil then return 'unreadable' end
    local key = model .. '/' .. selection
    for item in entry[2]:gmatch('%S+') do
        if item == key then return 'yes' end
    end
    return 'NO (catalog: ' .. (entry[2] ~= '' and entry[2] or 'none') .. ')'
end

local onHit

local function arm(e, rec)
    local bp = breakpoints_model_effect_catalog[rec.address]
    if bp == nil then
        if breakpointCount >= MAX_BREAKPOINTS then
            rec.state = 'not armed (breakpoint cap)'
            unarmed = unarmed + 1
            return
        end
        local address = rec.address
        bp = traceAddBreakpoint(address, 'Exec', 4,
                                SCRIPT_NAME .. ': ' .. rec.name,
                                function()
                                    local ok, err = pcall(onHit, address)
                                    if not ok and callbackError == nil then
                                        callbackError = tostring(err)
                                    end
                                end)
        breakpoints_model_effect_catalog[address] = bp
        breakpointCount = breakpointCount + 1
    else
        pcall(function() bp:enable() end)
    end
    targets[rec.address] = rec
    rec.state = 'armed'
end

-- Arms every function whose first word has arrived; the rest wait.
local function armPending(e)
    if e.pending == 0 then return end
    for _, rec in ipairs(e.funcs) do
        if rec.state == 'waiting' then
            if u32(rec.address) == rec.word then
                arm(e, rec)
                e.pending = e.pending - 1
            elseif frames - e.startFrame >= SIGNATURE_WAIT_FRAMES then
                rec.state = 'not armed (signature mismatch)'
                mismatched = mismatched + 1
                e.pending = e.pending - 1
            end
        end
    end
end

local function disarm(e)
    for _, rec in ipairs(e.funcs) do
        if targets[rec.address] == rec then
            targets[rec.address] = nil
            local bp = breakpoints_model_effect_catalog[rec.address]
            if bp ~= nil then pcall(function() bp:disable() end) end
        end
    end
end

local function closeEpisode(slot, reason)
    local e = current[slot]
    if e == nil then return end
    current[slot] = nil
    closed = closed + 1
    disarm(e)
    local header = string.format('#%02d slot=%d header=%d %s model=%s %s '
                                 .. 'selection=%s expected=%s frames=%d',
                                 e.number, slot, e.header, e.name,
                                 show(e.model), card(e.model, e.selection),
                                 show(e.selection), e.expected,
                                 frames - e.startFrame)
    summaries[#summaries + 1] = header
    for _, rec in ipairs(e.funcs) do
        local detail
        if rec.state ~= 'armed' and rec.state ~= 'waiting' then
            detail = rec.state
        elseif rec.hits == 0 then
            detail = rec.state == 'waiting' and 'never armed (code not loaded)'
                or 'hits=0'
        else
            detail = string.format('hits=%d first=+%.1fs', rec.hits,
                                   (rec.first - e.startFrame) / FPS)
        end
        summaries[#summaries + 1] = string.format('#%02d   +0x%04X %s %s',
                                                  e.number, rec.offset,
                                                  rec.name, detail)
    end
    live(string.format('#%02d %s END   slot=%d reason=%s', e.number, stamp(),
                       slot, reason))
end

local function openEpisode(slot, header, w)
    local entry = CATALOG[slot][header]
    local base = SLOTS + slot * SLOT_SIZE
    episodes = episodes + 1
    local model = u16(base + MODEL_ID)
    local selection = u8(base + GUARDIAN_STAR)
    local e = {number = episodes, header = header, work = w,
               startFrame = frames, name = entry[1], model = model,
               selection = selection,
               expected = expected(entry, model, selection),
               funcs = {}, pending = 0}
    current[slot] = e
    for _, f in ipairs(entry[3]) do
        e.funcs[#e.funcs + 1] = {address = BASES[slot] + f[1], offset = f[1],
                                 word = f[2], name = f[3], hits = 0,
                                 state = 'waiting', slot = slot, episode = e}
        e.pending = e.pending + 1
    end
    live(string.format('#%02d %s START slot=%d header=%d %s model=%s %s '
                       .. 'selection=%s expected=%s work=0x%08X functions=%d%s',
                       e.number, stamp(), slot, header, e.name, show(model),
                       card(model, selection), show(selection), e.expected, w,
                       #e.funcs, frames == 1 and ' (resident at load)' or ''))
    armPending(e)
end

local function finish(reason)
    if done then return end
    done = true
    for _, bp in pairs(breakpoints_model_effect_catalog) do
        pcall(function() bp:disable() end)
    end
    for slot = 0, 1 do
        if current[slot] ~= nil then closeEpisode(slot, 'still running') end
    end
    local lines = {
        '',
        '==== USER CONTEXT ====',
        '',
        '<one line per #NN: which monster attacked which, the guardian star',
        ' each had, and what the effect looked like (shapes, colours, motion),',
        ' with the t= of distinctive moments>',
        '',
        '==== TRACE RESULT =====',
        '',
        'script: ' .. SCRIPT_NAME,
    }
    for _, line in ipairs(lines) do say(line) end
    print('setup: ' .. TRACE_SETUP .. ' ' .. traceExecutionStatus())
    say('status: ' .. reason)
    say(string.format('frames: %d episodes: %d breakpoints: %d '
                      .. 'stray_hits: %d foreign_hits: %d '
                      .. 'signature_mismatches: %d unarmed: %d '
                      .. 'dropped_rows: %d', frames, episodes,
                      breakpointCount, stray, foreign, mismatched, unarmed,
                      dropped))
    if episodes == 0 then
        say('no variant image loaded: no 3D battle played while the script '
            .. 'ran (the CPU attacking skips it)')
    end
    if callbackError ~= nil then say('callback_error: ' .. callbackError) end
    say('')
    for _, line in ipairs(summaries) do say('summary ' .. line) end
    say('')
    for _, line in ipairs(rows) do say(line) end
    say('')
    say('--- end of trace, copy everything above into '
        .. 'tools/trace/result/' .. SCRIPT_NAME .. '.txt ---')
end

onHit = function(address)
    if done then return end
    local rec = targets[address]
    if rec == nil or current[rec.slot] ~= rec.episode then
        stray = stray + 1
        return
    end
    local e = rec.episode
    if u32(BASES[rec.slot]) ~= e.header then
        foreign = foreign + 1
        return
    end
    if u32(address) ~= rec.word then
        mismatched = mismatched + 1
        return
    end
    rec.hits = rec.hits + 1
    if rec.first == nil then
        rec.first = frames
        if hitRows < MAX_HIT_ROWS then
            hitRows = hitRows + 1
            local regs = PCSX.getRegisters()
            local ra = regs and regs.GPR and tonumber(regs.GPR.n.ra) or nil
            live(string.format('#%02d %s first +0x%04X %s slot=%d ra=%s',
                               e.number, stamp(), rec.offset, rec.name,
                               rec.slot, show(ra, '0x%08X')))
        end
    end
end

local function pollSlot(slot)
    local header = u32(BASES[slot])
    local w = work(slot)
    local e = current[slot]
    if e ~= nil and (header ~= e.header or w ~= e.work) then
        closeEpisode(slot, 'image unloaded or work area changed')
        e = nil
    end
    if e ~= nil then
        armPending(e)
        return
    end
    local seen = lastSeen[slot]
    lastSeen[slot] = header
    if header == nil or header == 0 or w == nil then return end
    if CATALOG[slot][header] == nil then
        if header ~= seen and header < 0x1000
            and unknownRows < MAX_UNKNOWN_ROWS then
            unknownRows = unknownRows + 1
            live(string.format('%s UNKNOWN header=%d slot=%d work=0x%08X: '
                               .. 'not in the catalog', stamp(), header, slot,
                               w))
        end
        return
    end
    if episodes < MAX_EPISODES then openEpisode(slot, header, w) end
end

local function poll()
    if done then return end
    frames = frames + 1
    if callbackError ~= nil then
        finish('callback error')
        return
    end
    pollSlot(0)
    pollSlot(1)
    if closed >= MAX_EPISODES then
        finish('captured ' .. MAX_EPISODES .. ' episodes')
    elseif frames >= TIMEOUT_FRAMES then
        finish('five minutes elapsed')
    end
end

-- Breakpoints are added per episode and kept here, keyed by address, so a
-- later image can re-enable them. Reloading the script replaces these.
breakpoints_model_effect_catalog = {}

listeners_model_effect_catalog = {
    PCSX.Events.createEventListener('GPU::Vsync', function()
        local ok, err = pcall(poll)
        if not ok then
            callbackError = callbackError or tostring(err)
            pcall(finish, 'script error: ' .. tostring(err))
        end
    end),
    PCSX.Events.createEventListener('ExecutionFlow::Reset', function()
        pcall(finish, 'reset; reload the script and start again')
    end),
}

say(SCRIPT_NAME .. ': armed; breakpoints follow each loaded variant image. '
    .. 'Attack now; the document prints after ' .. MAX_EPISODES
    .. ' episodes or five minutes')
